import { beforeEach, expect } from 'vitest'
import { openDatabase } from '../db.server'
import { createProjectStore, type ProjectStore } from '../projects.server'
import { handleAgentRequest } from './agentInterface.server'

export interface AgentHarness {
  store: ProjectStore
  advance(ms: number): void
  post(body: unknown, headers?: Record<string, string>): Promise<Response>
  rpc(method: string, params?: unknown): Promise<{ result?: any; error?: { code: number; message: string } }>
  /** Calls a tool; a successful result is its JSON, a tool error is { error: message } (or its JSON when it has details). */
  call(name: string, args?: Record<string, unknown>): Promise<any>
}

/** Registers a beforeEach that gives every test a fresh store; read `h.store` inside tests. */
export function agentHarness(): AgentHarness {
  let time = 0
  let nextId = 1
  const h: AgentHarness = {
    store: undefined as unknown as ProjectStore,
    advance: (ms) => {
      time += ms
    },
    post: (body, headers = {}) =>
      handleAgentRequest(
        new Request('http://localhost:3000/mcp', {
          method: 'POST',
          headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream', ...headers },
          body: JSON.stringify(body),
        }),
        h.store,
      ),
    async rpc(method, params) {
      const res = await h.post({ jsonrpc: '2.0', id: nextId++, method, params })
      expect(res.status).toBe(200)
      return (await res.json()) as { result?: any; error?: { code: number; message: string } }
    },
    async call(name, args = {}) {
      const { result, error } = await h.rpc('tools/call', { name, arguments: args })
      if (error) return { protocolError: error.message }
      const text = result.content[0].text as string
      if (!result.isError) return JSON.parse(text)
      try {
        const details = JSON.parse(text)
        if (details && typeof details === 'object' && typeof details.error === 'string') return details
      } catch {
        // a plain message
      }
      return { error: text }
    },
  }
  beforeEach(() => {
    time = Date.parse('2026-01-01T10:00:00.000Z')
    h.store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
  })
  return h
}
